// «Un cuadrado es un rectángulo», en matemática. En código, depende de qué se le prometa al cliente.
class Rectangulo {
  constructor(ancho, alto) { this.ancho = ancho; this.alto = alto; }
  setAncho(w) { this.ancho = w; }   // promete: cambia el ancho y deja el alto como estaba
  setAlto(h) { this.alto = h; }
  area() { return this.ancho * this.alto; }
}
class Cuadrado extends Rectangulo {
  constructor(lado) { super(lado, lado); }
  setAncho(w) { this.ancho = w; this.alto = w; }  // para seguir siendo cuadrado, cambia también el alto
  setAlto(h) { this.ancho = h; this.alto = h; }
}

// Un cliente que usa «cualquier rectángulo» y confía en la promesa de la clase base:
function ensancharEn(r, extra) {
  const altoAntes = r.alto, anchoAntes = r.ancho;
  r.setAncho(anchoAntes + extra);
  const esperado = (anchoAntes + extra) * altoAntes;
  console.log(`${r.constructor.name}: área esperada ${esperado}, área real ${r.area()}`);
}
ensancharEn(new Rectangulo(4, 3), 2);
ensancharEn(new Cuadrado(4), 2);

// Caso inventado: una flota de reparto.
class Camioneta {
  cargar(bulto) {                       // contrato publicado: acepta cualquier bulto de hasta 80 kg
    if (bulto.kg > 80) throw new Error("excede 80 kg");
    return `${this.constructor.name} lleva ${bulto.id}`;
  }
}
class Moto extends Camioneta {
  cargar(bulto) {
    if (bulto.largoCm > 60) throw new Error("no entra en el baúl");   // condición nueva, que la base no declara
    return super.cargar(bulto);
  }
}

const flota = [new Camioneta(), new Moto()];
const bultos = [{ id: "A", kg: 5, largoCm: 30 }, { id: "B", kg: 12, largoCm: 150 }, { id: "C", kg: 8, largoCm: 40 }];

// El planificador reparte los bultos por turnos y no sabe de qué clase es cada vehículo:
// le alcanza con la promesa de la base («hasta 80 kg»).
try {
  bultos.forEach((b, i) => console.log(flota[i % flota.length].cargar(b)));
} catch (e) {
  console.log("SE CAYÓ EL PLAN:", e.message);
}

// Arreglo: la condición se vuelve parte del contrato, y el cliente puede consultarla
class Camioneta {
  acepta(bulto) { return bulto.kg <= 80; }
  cargar(bulto) {
    if (!this.acepta(bulto)) throw new Error(`${this.constructor.name} no acepta ${bulto.id}`);
    return `${this.constructor.name} lleva ${bulto.id}`;
  }
}
class Moto extends Camioneta {
  acepta(bulto) { return bulto.largoCm <= 60 && super.acepta(bulto); }   // más estricta, pero DECLARADA
}
const flota = [new Camioneta(), new Moto()];
const bultos = [{ id: "A", kg: 5, largoCm: 30 }, { id: "B", kg: 12, largoCm: 150 }];
for (const b of bultos) {
  const v = flota.find((x) => x.acepta(b));
  console.log(`${b.id} -> ${v ? v.cargar(b) : "sin vehículo"}`);
}

// ANTES: una interfaz gorda
interface Transportista {
  retirar(bultoId: string): void;
  entregar(bultoId: string, firma: string): void;
  cobrarContrareembolso(bultoId: string, monto: number): void;
  imprimirEtiqueta(bultoId: string): string;
  rastrear(bultoId: string): string;
}

// La pantalla de seguimiento solo necesita rastrear...
function pantallaSeguimiento(t: Transportista, id: string): string {
  return `Tu envío ${id}: ${t.rastrear(id)}`;
}

// ...pero el doble de prueba tiene que cumplir con todo
const falso: Transportista = {
  rastrear: () => "en camino",
};
console.log(pantallaSeguimiento(falso, "A-17"));

// DESPUÉS: cada cliente declara lo que necesita
interface Rastreable { rastrear(bultoId: string): string; }
interface Entregador { entregar(bultoId: string, firma: string): void; }
interface ConEtiqueta { imprimirEtiqueta(bultoId: string): string; }

// Una clase puede cumplir todos los papeles...
class TransportistaReal implements Rastreable, Entregador, ConEtiqueta {
  rastrear(id: string) { return "en camino"; }
  entregar(id: string, firma: string) { console.log(`entregado ${id} firma=${firma}`); }
  imprimirEtiqueta(id: string) { return `ETQ-${id}`; }
}

// ...pero cada pantalla depende solo del suyo
function pantallaSeguimiento(t: Rastreable, id: string): string {
  return `Tu envío ${id}: ${t.rastrear(id)}`;
}

console.log(pantallaSeguimiento({ rastrear: () => "en camino" }, "A-17")); // el doble de una línea
console.log(pantallaSeguimiento(new TransportistaReal(), "A-17"));        // y el real, sin cambios

// ANTES: la regla de negocio crea y conoce al proveedor de mensajes
const enviadosReales = [];                       // en producción esto sería una llamada de red que cuesta plata
class ProveedorSms {
  enviar(tel, texto) { enviadosReales.push(`SMS a ${tel}: ${texto}`); }
}

class Despachador {
  constructor() { this.sms = new ProveedorSms(); }          // dependencia creada adentro
  despachar(pedido) {
    const hora = new Date().getHours();                      // y el reloj del sistema, también escondido
    if (hora >= 21) return "fuera de horario";
    this.sms.enviar(pedido.tel, `Tu pedido ${pedido.id} salió`);
    return "despachado";
  }
}

// ¿Cómo se prueba? El resultado depende de la hora a la que corras la prueba y manda un SMS de verdad.
console.log(new Despachador().despachar({ id: 7, tel: "1155550000" }), "(depende de la hora en que lo corras)");
console.log("SMS emitidos por la prueba:", enviadosReales.length);

// DESPUÉS: la regla de negocio declara lo que necesita y se lo entregan desde afuera
class Despachador {
  // «avisos» necesita un método enviar(tel, texto); «ahora» es una función que devuelve la hora
  constructor(avisos, ahora) { this.avisos = avisos; this.ahora = ahora; }
  despachar(pedido) {
    if (this.ahora().getHours() >= 21) return "fuera de horario";
    this.avisos.enviar(pedido.tel, `Tu pedido ${pedido.id} salió`);
    return "despachado";
  }
}

// Doble de prueba: anota en memoria, no manda nada
class AvisosEnMemoria {
  constructor() { this.enviados = []; }
  enviar(tel, texto) { this.enviados.push({ tel, texto }); }
}

// Prueba 1: de día
let avisos = new AvisosEnMemoria();
let d = new Despachador(avisos, () => new Date("2026-11-16T10:00:00"));
console.log(d.despachar({ id: 7, tel: "1155550000" }), JSON.stringify(avisos.enviados));

// Prueba 2: de noche, siempre da lo mismo sin importar cuándo se corra
avisos = new AvisosEnMemoria();
d = new Despachador(avisos, () => new Date("2026-11-16T22:30:00"));
console.log(d.despachar({ id: 8, tel: "1155550001" }), JSON.stringify(avisos.enviados));

// Producción: el único lugar que conoce las piezas reales
class ProveedorSms { enviar(tel, texto) { console.log(`[SMS real] ${tel}: ${texto}`); } }
const produccion = new Despachador(new ProveedorSms(), () => new Date("2026-11-16T09:15:00"));
produccion.despachar({ id: 9, tel: "1155550002" });
